/// <summary>
/// Web page changed: A web source's page failed to load (it's see-through on air and tried again by itself), failed for another reason, or loaded. (<c>web.changed</c>, from the <c>web</c> topic)
/// </summary>
public sealed record WebChangedEvent : StudioEvent
{
    /// <inheritdoc/>
    [JsonIgnore]
    public override EventType Type => EventType.WebChanged;

    /// <summary>
    /// Why it failed (see the web topic); null unless failed.
    /// </summary>
    [JsonPropertyName("code")]
    public string? Code { get; init; }

    /// <summary>
    /// Why it failed, in plain words; null unless failed.
    /// </summary>
    [JsonPropertyName("message")]
    public string? Message { get; init; }

    [JsonPropertyName("name")]
    public string Name { get; init; } = "";

    /// <summary>
    /// The web source's id.
    /// </summary>
    [JsonPropertyName("source")]
    public string Source { get; init; } = "";

    [JsonPropertyName("state")]
    public WebPageState State { get; init; }

    [JsonPropertyName("url")]
    public string? Url { get; init; }

    /// <summary>
    /// Its state before.
    /// </summary>
    [JsonPropertyName("was")]
    public WebPageState Was { get; init; }
}

public sealed partial class VelumStudioClient
{
    /// <summary>
    /// Scene changed: A scene went on air. Subscribe to the <c>scenes</c> topic to get it.
    /// </summary>
    public event EventHandler<SceneChangedEvent>? SceneChanged;

    /// <summary>
    /// Chat message: A chat message arrived on any platform, including messages sent from Studio, /me actions, channel notices, bot replies and announcements (kind says which). Subscribe to the <c>chat</c> topic to get it.
    /// </summary>
    public event EventHandler<ChatMessageEvent>? ChatMessage;

    /// <summary>
    /// Chat messages deleted: A moderator (or a ban or timeout) removed chat messages. Subscribe to the <c>chat</c> topic to get it.
    /// </summary>
    public event EventHandler<ChatDeletedEvent>? ChatDeleted;

    /// <summary>
    /// Chat message edited: A chat message was edited. Subscribe to the <c>chat</c> topic to get it.
    /// </summary>
    public event EventHandler<ChatEditedEvent>? ChatEdited;

    /// <summary>
    /// Chat cleared: A platform's chat was cleared for everyone. Subscribe to the <c>chat</c> topic to get it.
    /// </summary>
    public event EventHandler<ChatClearedEvent>? ChatCleared;

    /// <summary>
    /// Follow: Someone followed. Subscribe to the <c>activity</c> topic to get it.
    /// </summary>
    public event EventHandler<ActivityFollowEvent>? ActivityFollow;

    /// <summary>
    /// Subscription: Someone subscribed. Subscribe to the <c>activity</c> topic to get it.
    /// </summary>
    public event EventHandler<ActivitySubEvent>? ActivitySub;

    /// <summary>
    /// Resubscription: Someone renewed their subscription and said so. Subscribe to the <c>activity</c> topic to get it.
    /// </summary>
    public event EventHandler<ActivityResubEvent>? ActivityResub;

    /// <summary>
    /// Gifted subscriptions: Someone gifted subscriptions (amount.value is how many, with unit subs). Subscribe to the <c>activity</c> topic to get it.
    /// </summary>
    public event EventHandler<ActivityGiftSubEvent>? ActivityGiftSub;

    /// <summary>
    /// Support: Support with an amount: Velora Volts, Twitch bits, Kick KICKs, YouTube Super Chats. amount says how much and in what unit. Subscribe to the <c>activity</c> topic to get it.
    /// </summary>
    public event EventHandler<ActivitySupportEvent>? ActivitySupport;

    /// <summary>
    /// Redemption: A channel-points (or Kick rewards) redemption. title is the reward's. Subscribe to the <c>activity</c> topic to get it.
    /// </summary>
    public event EventHandler<ActivityRedemptionEvent>? ActivityRedemption;

    /// <summary>
    /// Raid: Another channel raided this one. amount.value is how many viewers came, when the platform says. Subscribe to the <c>activity</c> topic to get it.
    /// </summary>
    public event EventHandler<ActivityRaidEvent>? ActivityRaid;

    /// <summary>
    /// Card: A poll, prediction, giveaway, goal or clip, shown as a card. It may change in place later (activity.updated). Subscribe to the <c>activity</c> topic to get it.
    /// </summary>
    public event EventHandler<ActivityCardEvent>? ActivityCard;

    /// <summary>
    /// Activity updated: An activity row changed in place, such as a poll's votes; same eid as before. Subscribe to the <c>activity</c> topic to get it.
    /// </summary>
    public event EventHandler<ActivityUpdatedEvent>? ActivityUpdated;

    /// <summary>
    /// Recording paused: The recording was paused: nothing more goes in until it resumes. Subscribe to the <c>record</c> topic to get it.
    /// </summary>
    public event EventHandler<RecordPausedEvent>? RecordPaused;

    /// <summary>
    /// Recording resumed: The recording carries on in the same file, with no gap in its timeline. Subscribe to the <c>record</c> topic to get it.
    /// </summary>
    public event EventHandler<RecordResumedEvent>? RecordResumed;

    /// <summary>
    /// Replay buffer started: The replay buffer started keeping the last seconds of what's on air. Subscribe to the <c>replay</c> topic to get it.
    /// </summary>
    public event EventHandler<ReplayStartedEvent>? ReplayStarted;

    /// <summary>
    /// Replay buffer stopped: The replay buffer stopped; what it held was let go. Subscribe to the <c>replay</c> topic to get it.
    /// </summary>
    public event EventHandler<ReplayStoppedEvent>? ReplayStopped;

    /// <summary>
