    /// <summary>
    /// Web page changed: A web source's page failed to load (it's see-through on air and tried again by itself), failed for another reason, or loaded. Subscribe to the <c>web</c> topic to get it.
    /// </summary>
    public event EventHandler<WebChangedEvent>? WebChanged;

    private partial StudioEvent? ReadEvent(string method, JsonElement data) => method switch
    {
        "scene.changed" => data.Deserialize(VelumJson.Info<SceneChangedEvent>()),
        "chat.message" => data.Deserialize(VelumJson.Info<ChatMessageEvent>()),
        "chat.deleted" => data.Deserialize(VelumJson.Info<ChatDeletedEvent>()),
        "chat.edited" => data.Deserialize(VelumJson.Info<ChatEditedEvent>()),
        "chat.cleared" => data.Deserialize(VelumJson.Info<ChatClearedEvent>()),
        "activity.follow" => data.Deserialize(VelumJson.Info<ActivityFollowEvent>()),
        "activity.sub" => data.Deserialize(VelumJson.Info<ActivitySubEvent>()),
        "activity.resub" => data.Deserialize(VelumJson.Info<ActivityResubEvent>()),
        "activity.gift_sub" => data.Deserialize(VelumJson.Info<ActivityGiftSubEvent>()),
        "activity.support" => data.Deserialize(VelumJson.Info<ActivitySupportEvent>()),
        "activity.redemption" => data.Deserialize(VelumJson.Info<ActivityRedemptionEvent>()),
        "activity.raid" => data.Deserialize(VelumJson.Info<ActivityRaidEvent>()),
        "activity.card" => data.Deserialize(VelumJson.Info<ActivityCardEvent>()),
        "activity.updated" => data.Deserialize(VelumJson.Info<ActivityUpdatedEvent>()),
        "record.paused" => data.Deserialize(VelumJson.Info<RecordPausedEvent>()),
        "record.resumed" => data.Deserialize(VelumJson.Info<RecordResumedEvent>()),
        "replay.started" => data.Deserialize(VelumJson.Info<ReplayStartedEvent>()),
        "replay.stopped" => data.Deserialize(VelumJson.Info<ReplayStoppedEvent>()),
        "replay.saved" => data.Deserialize(VelumJson.Info<ReplaySavedEvent>()),
        "media.changed" => data.Deserialize(VelumJson.Info<MediaChangedEvent>()),
        "obs.custom_event" => data.Deserialize(VelumJson.Info<ObsCustomEventEvent>()),
        "web.changed" => data.Deserialize(VelumJson.Info<WebChangedEvent>()),
        _ => null,
    };

    private partial void RaiseTyped(StudioEvent e)
    {
        switch (e)
        {
            case SceneChangedEvent x: SceneChanged?.Invoke(this, x); break;
            case ChatMessageEvent x: ChatMessage?.Invoke(this, x); break;
            case ChatDeletedEvent x: ChatDeleted?.Invoke(this, x); break;
            case ChatEditedEvent x: ChatEdited?.Invoke(this, x); break;
            case ChatClearedEvent x: ChatCleared?.Invoke(this, x); break;
            case ActivityFollowEvent x: ActivityFollow?.Invoke(this, x); break;
            case ActivitySubEvent x: ActivitySub?.Invoke(this, x); break;
            case ActivityResubEvent x: ActivityResub?.Invoke(this, x); break;
            case ActivityGiftSubEvent x: ActivityGiftSub?.Invoke(this, x); break;
            case ActivitySupportEvent x: ActivitySupport?.Invoke(this, x); break;
            case ActivityRedemptionEvent x: ActivityRedemption?.Invoke(this, x); break;
            case ActivityRaidEvent x: ActivityRaid?.Invoke(this, x); break;
            case ActivityCardEvent x: ActivityCard?.Invoke(this, x); break;
            case ActivityUpdatedEvent x: ActivityUpdated?.Invoke(this, x); break;
            case RecordPausedEvent x: RecordPaused?.Invoke(this, x); break;
            case RecordResumedEvent x: RecordResumed?.Invoke(this, x); break;
            case ReplayStartedEvent x: ReplayStarted?.Invoke(this, x); break;
            case ReplayStoppedEvent x: ReplayStopped?.Invoke(this, x); break;
            case ReplaySavedEvent x: ReplaySaved?.Invoke(this, x); break;
            case MediaChangedEvent x: MediaChanged?.Invoke(this, x); break;
            case ObsCustomEventEvent x: ObsCustomEvent?.Invoke(this, x); break;
            case WebChangedEvent x: WebChanged?.Invoke(this, x); break;
        }
    }
}
